import ebUrls from '../../../../../request/urls/employeeBenefit'

export const BANNER_ACTIONS = {
  GET_POSSIBLE_POSITIONS_REQUEST: 'GET_POSSIBLE_POSITIONS_REQUEST',
  GET_POSSIBLE_POSITIONS: 'GET_POSSIBLE_POSITIONS',
  BANNER_LIST_REQUEST: 'BANNER_LIST_REQUEST',
  BANNER_LIST: 'BANNER_LIST',
  ADD_BANNER_REQUEST: 'ADD_BANNER_REQUEST',
  ADD_BANNER: 'ADD_BANNER',
  REMOVE_BANNER_REQUEST: 'REMOVE_BANNER_REQUEST',
  REMOVE_BANNER: 'REMOVE_BANNER',
  UPDATE_BANNER_REQUEST: 'UPDATE_BANNER_REQUEST',
  UPDATE_BANNER: 'UPDATE_BANNER',
  updateBannerRequest: ({ bannerId, ...payload }) => ({
    type: BANNER_ACTIONS.UPDATE_BANNER_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateBanner(bannerId)
    }
  }),
  addBannerRequest: payload => ({
    type: BANNER_ACTIONS.ADD_BANNER_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.addBanner
    }
  }),
  getBannerList: payload => ({
    type: BANNER_ACTIONS.BANNER_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.bannerList
    }
  }),
  getPossiblePositions: payload => ({
    type: BANNER_ACTIONS.GET_POSSIBLE_POSITIONS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getPossibleBannerPositions
    }
  }),
  removeBanner: bannerId => ({
    type: BANNER_ACTIONS.REMOVE_BANNER_REQUEST,
    payload: {
      method: 'delete',
      url: ebUrls.removeBanner(bannerId)
    }
  }),
  resetState: keys => ({
    type: BANNER_ACTIONS.RESET_STATE,
    payload: keys
  })
}
