/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import { Form, Row, Col, Input, Button, Select, Spin, Alert, message } from 'antd'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { FORM_FIELDS, rules } from './validations'
import { ColTextAlignRight } from '../../../CommonComponents/index.style'
import { useDashboardBannerContext } from '../../../state/DashboardBanner/hooks/useDashboardBanner'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import lodash from 'lodash'
import FileUploadOnGcsV2 from '../../../../../../components/FileUploadOnGcsV2'

const { Item } = Form
// const { TextArea } = Input
const { Option } = Select

const AddDashboardBanner = ({ history, form }) => {
  const { getFieldDecorator } = form
  const { getPossiblePositionsRequest, getPossiblePositionsData, addBannerRequest, updateBannerRequest } = useDashboardBannerContext()
  const [{ GET_POSSIBLE_POSITIONS_LOADER, ADD_BANNER_LOADER, UPDATE_BANNER_LOADER }] = useLoaderContextValue()
  const [{
    ADD_BANNER_ERROR,
    addBannerStatus,
    addBannerErrorData,
    GET_POSSIBLE_POSITIONS_ERROR,
    getPossiblePositionsStatus,
    UPDATE_BANNER_ERROR,
    updateBannerStatus,
    updateBannerErrorData
  }] = useErrorContextValue()
  const { resetError } = useResetError()
  const editBannerData = history.location.state

  const handleSubmit = () => {
    form.validateFields((error, values) => {
      resetError(['updateBannerStatus', 'addBannerStatus'])
      if (!error) {
        const toBeSentValues = { ...values }
        toBeSentValues[FORM_FIELDS.imageUrl] = Array.isArray(values[FORM_FIELDS.imageUrl]) && values[FORM_FIELDS.imageUrl].length
          ? values[FORM_FIELDS.imageUrl][0]?.url
          : undefined
        toBeSentValues[FORM_FIELDS.link] = toBeSentValues[FORM_FIELDS.link] || null
        toBeSentValues[FORM_FIELDS.bodyCopy] = toBeSentValues[FORM_FIELDS.bodyCopy] || null
        if (editBannerData) {
          updateBannerRequest({ id: editBannerData.id, ...toBeSentValues })
        } else {
          addBannerRequest(toBeSentValues)
        }
      }
    })
  }

  useEffect(() => {
    if (updateBannerErrorData && updateBannerErrorData.error) {
      const { error } = updateBannerErrorData
      if (error[FORM_FIELDS.position]) {
        getPossiblePositionsRequest({ id: editBannerData.id })
      }
      const values = form.getFieldsValue()
      for (const key in error) {
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [updateBannerErrorData])

  useEffect(() => {
    if (addBannerErrorData && addBannerErrorData.error) {
      const { error } = addBannerErrorData
      if (error[FORM_FIELDS.position]) {
        getPossiblePositionsRequest()
      }
      const values = form.getFieldsValue()
      for (const key in error) {
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [addBannerErrorData])

  useEffect(() => {
    if (editBannerData) {
      form.setFieldsValue({
        [FORM_FIELDS.position]: editBannerData[FORM_FIELDS.position],
        [FORM_FIELDS.title]: editBannerData[FORM_FIELDS.title],
        [FORM_FIELDS.bodyCopy]: editBannerData[FORM_FIELDS.bodyCopy],
        [FORM_FIELDS.link]: editBannerData[FORM_FIELDS.link]
      })
    }
  }, [editBannerData])

  useEffect(() => {
    if (updateBannerStatus === 'success') {
      message.success('Banner updated successfully')
      history.push('/employee-benefits/dashboard-banner/')
    }
  }, [updateBannerStatus])

  useEffect(() => {
    if (addBannerStatus === 'success') {
      message.success('Banner added successfully')
      history.push('/employee-benefits/dashboard-banner/')
    }
  }, [addBannerStatus])

  useEffect(() => {
    if (Array.isArray(getPossiblePositionsData) && !getPossiblePositionsData.length) {
      message.error('You’ve reached the maximum banner slot of 4. Please delete one to create new banner.')
      history.push('/employee-benefits/dashboard-banner/')
    }
  }, [getPossiblePositionsData])

  useEffect(() => {
    const query = { id: editBannerData && editBannerData.id }
    getPossiblePositionsRequest(query)
    return () => {
      resetError([
        'updateBannerStatus',
        'UPDATE_BANNER_ERROR',
        'addBannerStatus',
        'ADD_BANNER_ERROR',
        'addBannerErrorData',
        'updateBannerErrorData'
      ])
    }
  }, [])

  return (
    <EbEmptyPage
      history={history}
      path='/employee-benefits/dashboard-banner/'
    >
      {(GET_POSSIBLE_POSITIONS_ERROR) && <Alert type='error' message={getPossiblePositionsStatus} banner />}
      {(ADD_BANNER_ERROR) && !lodash.get(addBannerErrorData, 'error') && <Alert type='error' message={addBannerStatus} banner />}
      {(UPDATE_BANNER_ERROR) && !lodash.get(updateBannerErrorData, 'error') && <Alert type='error' message={updateBannerStatus} banner />}
      <h2>Add Banner Details</h2>
      <Spin
        spinning={!!GET_POSSIBLE_POSITIONS_LOADER || !!ADD_BANNER_LOADER || !!UPDATE_BANNER_LOADER}
      >
        <Form>
          <Row gutter={18}>
            <Col span={6}>
              <Item
                hasFeedback
                label='Title'
                required
              >
                {
                  getFieldDecorator(
                    FORM_FIELDS.title,
                    {
                      validateTrigger: ['onBlur'],
                      rules: rules[FORM_FIELDS.title]
                    }
                  )(<Input />)
                }
              </Item>
            </Col>
            <Col span={6}>
              <Item
                hasFeedback
                label='Link'
              >
                {
                  getFieldDecorator(
                    FORM_FIELDS.link,
                    {
                      validateTrigger: ['onBlur'],
                      rules: rules[FORM_FIELDS.link]
                    }
                  )(<Input />)
                }
              </Item>
            </Col>
          </Row>
          <Row gutter={18}>
            <Col span={6}>
              <Item
                label='Position'
                hasFeedback
              >
                {
                  getFieldDecorator(
                    FORM_FIELDS.position,
                    {
                      validateTrigger: ['onBlur'],
                      rules: rules[FORM_FIELDS.position]
                    }
                  )(
                    <Select>
                      {
                        Array.isArray(getPossiblePositionsData) && getPossiblePositionsData.map(position => (
                          <Option value={position} key={position}>{position}</Option>
                        ))
                      }
                    </Select>
                  )
                }
              </Item>
            </Col>
            <Col span={6}>
              <FileUploadOnGcsV2
                required={!editBannerData}
                name={FORM_FIELDS.imageUrl}
                identifier='static_storage'
                accept='image/*'
                getFieldDecorator={getFieldDecorator}
                form={form}
                maxSize={2}
                maxFileAllowed={1}
                buttonClassName='width-150'
                icon='cloud-upload'
                formItemProps={{
                  label: 'Image',
                  required: !editBannerData,
                  extra: 'Expected dimension - 600x248',
                  hasFeedback: true
                }}
              />
            </Col>
          </Row>
          <Row gutter={18}>
            <Col span={12}>
              <Item
                hasFeedback
                label='Body Copy'
              >
                {
                  getFieldDecorator(
                    FORM_FIELDS.bodyCopy,
                    {
                      validateTrigger: ['onBlur'],
                      rules: rules[FORM_FIELDS.bodyCopy]
                    }
                  )(<Input />)
                }
              </Item>

            </Col>
          </Row>
          <Row gutter={18}>
            <ColTextAlignRight span={24}>
              <Button
                type='primary'
                htmlType='button'
                onClick={handleSubmit}
              >
                Submit
              </Button>
            </ColTextAlignRight>
          </Row>
        </Form>
      </Spin>
    </EbEmptyPage>
  )
}
export default Form.create('Add-banner-form')(AddDashboardBanner)
