import { mapArrayElementsKeysToObjectKeys } from '../../../../../helpers/utility'
import { BANNER_ACTIONS } from './actions'

const reducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case BANNER_ACTIONS.GET_POSSIBLE_POSITIONS:
    case BANNER_ACTIONS.BANNER_LIST:
    case BANNER_ACTIONS.ADD_BANNER:
    case BANNER_ACTIONS.REMOVE_BANNER:
    case BANNER_ACTIONS.UPDATE_BANNER:
      return { ...state, ...payload }
    case BANNER_ACTIONS.RESET_STATE:
      return { ...state, ...mapArrayElementsKeysToObjectKeys(payload) }
    default:
      return state
  }
}

export default reducer
