import _ from 'lodash'
import { Button, Upload, Icon, message, Form } from 'antd'
import { callWithTimeout } from '../../helpers/utility'
import uploadFileOnGcsV2Request from '../../request/methods/uploadFileOnGcsV2'
import ebUrls from '../../request/urls/employeeBenefit'
import { StyledWrapper } from './index.style'

const removeAllSpaces = (name = "") => {
  return name.replaceAll(" ", "_")
}

const FileUploadOnGcsV2 = ({
  getFieldDecorator,
  name,
  required = false,
  buttonClassName = '',
  buttonType = 'default',
  maxFileAllowed,
  multiple = false,
  form,
  minSize = 0.01, // min 10 Kb
  maxSize = 2, // max 2 MB
  identifier,
  initialValue,
  onPreview,
  buttonText = 'Upload',
  accept = '',
  formItemProps = {},
  icon,
  signedUrlEndPoint = ebUrls.generateSignedUrl,
  fileNameLength, // number providing the max length of the string allowed, default will be full,
  disabled = false,
  makeFileUrlPublic = false,
  onFileUploadedSuccess = () => { }
}) => {
  const normFile = (e) => {
    if (Array.isArray(e)) {
      if (maxFileAllowed) {
        return e.slice(-maxFileAllowed)
      }
      return e
    }
    if (maxFileAllowed) {
      return e && e.fileList && e.fileList.slice(-maxFileAllowed)
    }
    return e && e.fileList
  }

  const customRequest = (config) => {
    const { file, onSuccess, onError } = config
    const { size } = file
    const isLtMinSize = size / 1024 / 1024 < minSize
    const isGtMaxSize = size / 1024 / 1024 > maxSize
    if (isLtMinSize) {
      message.error('File is to small, min 10kb')
      callWithTimeout(config.onError)
      return
    }
    if (isGtMaxSize) {
      message.error(`File is to big, max ${maxSize} mb`)
      callWithTimeout(config.onError)
      return
    }
    return uploadFileOnGcsV2Request({
      signedUrl: signedUrlEndPoint,
      body: { file: config.file },
      makeFileUrlPublic: makeFileUrlPublic,
      signedUrlBody: { file_name: encodeURI(removeAllSpaces(file.name)), identifier: identifier || 'static_storage', content_type: file.type }
    })
      .then(res => {
        onFileUploadedSuccess()
        onSuccess(res)
      })
      .catch(err => onError(err))
  }

  const handleChange = info => {
    let fileList = [...info.fileList]
    // 1. Limit the number of uploaded files
    // Only to show two recent uploaded files, and old ones will be replaced by the new
    // if (maxFileAllowed) {
    //   fileList = fileList.slice(-maxFileAllowed)
    // }

    // 2. Read from response and show file link
    fileList = fileList.map(file => {
      if (file.response) {
        // Component will show file.url as link
        file.url = file.response.data.url
      }
      return file
    })

    if (fileNameLength) {
      fileList = fileList.map(item => {
        item.name = _.truncate(
          item.name, {
          length: fileNameLength
        }
        )
        return item
      })
    }
    form.setFieldsValue({ [name]: fileList })
  }

  const getButtonClass = () => {
    let buttonClass = `border-radius-ant-input ${buttonClassName}`
    const isFieldError = form.getFieldError(name)
    if (isFieldError) {
      buttonClass += ' form-error'
    }
    return buttonClass
  }

  return (
    <Form.Item {...formItemProps}>
      {
        getFieldDecorator(name, {
          valuePropName: 'fileList',
          initialValue: initialValue,
          getValueFromEvent: normFile,
          rules: [
            {
              required,
              message: 'This field is required.'
            }
          ]
        })(
          <Upload
            multiple={multiple === undefined || multiple}
            customRequest={customRequest}
            onChange={handleChange}
            {...(onPreview && { onPreview })}
            {...(accept && { accept })}
            disabled={disabled}
          >
            <StyledWrapper>
              <Button
                className={getButtonClass()}
                type={buttonType}
                disabled={disabled}
              >
                <Icon type={icon || 'upload'} /> {buttonText}
              </Button>
            </StyledWrapper>
          </Upload>
        )
      }
    </Form.Item>
  )
}
export default FileUploadOnGcsV2
